    MC("Qual é a ordem correta?", ["*Graag ontvang ik informatie.","Graag ik ontvang informatie.|Inversão depois de «Graag»."], "Inversão depois de «Graag».", ["v-taalschool"]),
    LI("Wanneer begint de volgende cursus?", ["Wanneer begint de volgende cursus","Wanneer begint de volgende cursus?"], "Quando começa o próximo curso?", "Pergunta.", ["v-cursus"]),
    WO("A taxa de inscrição é cinquenta euros.", ["Het","inschrijfgeld","is","vijftig","euro"], "Euro sem plural.", ["v-inschrijfgeld"]),
